edits.newText:
// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. Face resolution lives in resolveBricks() (swept), with
// resolveBrickOverlaps() as a fallback for pre-existing overlaps.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision (continuous) ------------------------------------------

// Entry of the ball-center segment (prevX,prevY -> ball.x,ball.y) into the
// brick's box expanded by the ball radius (slab method). Returns the entry
// time t in [0,1] and the axis of the entered face, or null when the segment
// never crosses the expanded box (including when it starts inside it — those
// overlaps go to resolveBrickOverlaps).
function sweptEntry(ball, brick, prevX, prevY, dx, dy) {
  const minX = brick.x - ball.r;
  const maxX = brick.x + brick.w + ball.r;
  const minY = brick.y - ball.r;
  const maxY = brick.y + brick.h + ball.r;

  let tEnter = 0;
  let tExit = 1;
  let axis = null;

  if (dx === 0) {
    if (prevX <= minX || prevX >= maxX) return null;
  } else {
    let t1 = (minX - prevX) / dx;
    let t2 = (maxX - prevX) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tEnter) {
      tEnter = t1;
      axis = 'x';
    }
    if (t2 < tExit) tExit = t2;
  }

  if (dy === 0) {
    if (prevY <= minY || prevY >= maxY) return null;
  } else {
    let t1 = (minY - prevY) / dy;
    let t2 = (maxY - prevY) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tEnter) {
      tEnter = t1;
      axis = 'y';
    }
    if (t2 < tExit) tExit = t2;
  }

  if (tEnter > tExit || tEnter <= 0 || tEnter > 1) return null;
  return { t: tEnter, axis };
}

// Resolves every brick hit by the ball's swept path in this step.
// One bounce per pass per axis: bricks entered at the same instant (seams,
// grid corners) share a single deflection and are all destroyed.
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let bestT = Infinity;
  const hitBricks = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const entry = sweptEntry(ball, brick, prevX, prevY, dx, dy);
    if (!entry) continue;
    if (entry.t < bestT - 1e-9) {
      bestT = entry.t;
      hitBricks.length = 0;
      hitBricks.push({ brick, axis: entry.axis });
    } else if (Math.abs(entry.t - bestT) <= 1e-9) {
      hitBricks.push({ brick, axis: entry.axis });
    }
  }

  if (hitBricks.length === 0) {
    // No swept crossing: the ball may already overlap a brick (dt = 0, a wall
    // push, the paddle teleporting). Resolve by penetration instead.
    resolveBrickOverlaps(state);
    return;
  }

  // One deflection: flip the axis of the earliest entry. If the earliest
  // entry is shared by faces of both axes (a grid corner), flip both.
  let flipX = false;
  let flipY = false;
  for (const { axis } of hitBricks) {
    if (axis === 'x') flipX = true;
    else flipY = true;
  }
  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;

  // Place the ball at the entry point: out of every brick it hit.
  ball.x = prevX + dx * bestT;
  ball.y = prevY + dy * bestT;

  // Destroy and score every brick hit in this pass, in grid order.
  for (const { brick } of hitBricks) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }
}

// Fallback for pre-existing overlaps: resolve each overlapping brick on its
// minimal-penetration axis (equal penetrations = corner: flip both axes),
// pushing the ball out. Bounded iterations: the push-out may create new
// overlaps (seams narrower than the ball).
function resolveBrickOverlaps(state) {
  const { ball } = state;
  for (let pass = 0; pass < 8; pass++) {
    let resolved = false;
    for (const brick of state.bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      resolved = true;

      const overlapX =
        Math.min(ball.x + ball.r, brick.x + brick.w) -
        Math.max(ball.x - ball.r, brick.x);
      const overlapY =
        Math.min(ball.y + ball.r, brick.y + brick.h) -
        Math.max(ball.y - ball.r, brick.y);

      if (Math.abs(overlapX - overlapY) < 1e-9) {
        // Corner: flip both axes.
        ball.vx = -ball.vx;
        ball.vy = -ball.vy;
        const cx = brick.x + brick.w / 2;
        const cy = brick.y + brick.h / 2;
        ball.x += ball.x < cx ? -overlapX : overlapX;
        ball.y += ball.y < cy ? -overlapY : overlapY;
      } else if (overlapX < overlapY) {
        ball.vx = -ball.vx;
        const cx = brick.x + brick.w / 2;
        ball.x += ball.x < cx ? -overlapX : overlapX;
      } else {
        ball.vy = -ball.vy;
        const cy = brick.y + brick.h / 2;
        ball.y += ball.y < cy ? -overlapY : overlapY;
      }
    }
    if (!resolved) return;
  }
}

