edits.newText:
// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the bricks (swept), the walls and the paddle.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const prevX = ball.x;
  const prevY = ball.y;
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Bricks: continuous (swept) resolution, one bounce per pass per axis.
  resolveBricks(state, prevX, prevY);

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: continuous test on its top face (a fast descent must not skip the
  // 12px band), plus an overlap fallback. The ball always leaves through the
  // top of the paddle.
  if (ball.vy > 0 && ball.x >= paddle.x && ball.x <= paddle.x + paddle.w) {
    const bottomEdge = ball.y + ball.r;
    const prevBottom = prevY + ball.r;
    const crossedTop = prevBottom < paddle.y && bottomEdge >= paddle.y;
    const overlapping = bottomEdge >= paddle.y && ball.y - ball.r <= paddle.y + paddle.h;
    if (crossedTop || overlapping) {
      ball.y = paddle.y - ball.r;
      // The rebound angle depends on where the paddle was hit, floored so a
      // center hit keeps a playable trajectory (no vertical dead loop).
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      const dir = hit >= 0 ? 1 : -1;
      const clamped = Math.max(Math.abs(hit), 0.1);
      const speed = ballSpeed(state.level);
      ball.vx = speed * 0.6 * dir * clamped;
      // Renormalize: the rebound keeps the level speed.
      ball.vy = -Math.sqrt(speed * speed - ball.vx * ball.vx);
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

