// neon.test.js — coverage of the physics and collision resolution.
//
// Collision is resolved continuously in step(): one bounce per pass per axis,
// swept entry face, push-out, and a renormalized paddle rebound. Score and
// combo are still partial (see ISSUES.md #5), as is level progression.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  ballSpeed,
  DOWN,
  PADDLE_Y,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

edits.oldText:
// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

edits.newText:
// Row 4 (bottom) col 3 brick: x=244..316, y=160..180.
function bottomBrick(state) {
  return state.bricks.find((b) => b.row === 4 && b.x === 244);
}

test('D1: underside hit deflects the ball down and out of the brick', () => {
  const state = createState(1);
  const brick = bottomBrick(state);
  // rising from below the brick; one 50ms step lands the ball inside it
  state.ball = { x: 280, y: 190, r: 7, vx: 0, vy: -ballSpeed(1) };
  step(state, 0.05);
  assert.equal(Math.sign(state.ball.vy), DOWN, 'must leave the underside with vy > 0');
  assert.equal(collides(state.ball, brick), false, 'ball must be pushed out of the brick');
  assert.equal(brick.alive, false, 'brick must be destroyed');
  assert.equal(state.combo, 1, 'combo increments once');
  assert.equal(state.score, 15, 'brick points scored (row 4, combo 1)');
});

test('D2 collant: after the bounce the ball is out and never re-inverts', () => {
  const state = createState(1);
  const brick = bottomBrick(state);
  state.ball = { x: 280, y: 190, r: 7, vx: 0, vy: -ballSpeed(1) };
  step(state, 0.05); // bounce
  assert.equal(collides(state.ball, brick), false, 'no sticking: ball pushed out');
  const vyAfterBounce = state.ball.vy;
  step(state, 0.05); // next step: must not re-collide / re-invert
  assert.equal(state.ball.vy, vyAfterBounce, 'no re-inversion on the next step');
  assert.equal(collides(state.ball, brick), false, 'ball stays out of the brick');
});

test('D3 axis: a side hit flips vx, not vy (deep x penetration, level 3)', () => {
  const state = createState(3);
  const brick = state.bricks.find((b) => b.row === 2 && b.x === 164); // col 2: x=164..236
  state.bricks.find((b) => b.row === 2 && b.x === 244).alive = false; // col 3 already broken
  // moving left toward col 2 right face (236); post (226,105) has overlap_x 14 > overlap_y 8
  // => a static minimal-penetration resolver picks y; only the swept entry (x=243) picks x.
  state.ball = { x: 248, y: 105, r: 7, vx: -ballSpeed(3), vy: 0 };
  step(state, 0.05);
  assert.ok(state.ball.vx > 0, 'horizontal velocity must flip on a side hit');
  assert.equal(state.ball.vy, 0, 'vertical velocity untouched on a side hit');
  assert.equal(collides(state.ball, brick), false, 'ball pushed out on the entered side');
});

test('D4 seam: two bricks at once invert vy exactly once (no ghost double flip)', () => {
  const state = createState(1);
  const L = state.bricks.find((b) => b.row === 0 && b.x === 4); //  [4,76]x[48,68]
  const R = state.bricks.find((b) => b.row === 0 && b.x === 84); // [84,156]x[48,68]
  // rising through the 8px seam (ball 14px): post position overlaps both bricks
  state.ball = { x: 80, y: 75.5, r: 7, vx: 0, vy: -ballSpeed(1) };
  step(state, 0.05);
  assert.equal(Math.sign(state.ball.vy), DOWN, 'one pass, one vy inversion');
  assert.equal(collides(state.ball, L), false, 'out of L');
  assert.equal(collides(state.ball, R), false, 'out of R');
  assert.equal(L.alive, false, 'L destroyed');
  assert.equal(R.alive, false, 'R destroyed');
});

test('D5 tunneling: level 6 + 50ms step (35.5px) > brick+ball (34px): swept bounce', () => {
  const state = createState(6);
  const brick = bottomBrick(state);
  // rising; NEITHER sample overlaps the brick, the swept path crosses it
  state.ball = { x: 280, y: 188, r: 7, vx: 0, vy: -ballSpeed(6) };
  step(state, 0.05);
  assert.equal(Math.sign(state.ball.vy), DOWN, 'crossed brick must bounce');
  assert.equal(brick.alive, false, 'brick destroyed although no sample overlapped');
  assert.equal(collides(state.ball, brick), false, 'ball out after the bounce');
});

test('D5b dt-independence: the same crossing bounces at every dt <= 50ms', () => {
  for (const dt of [1 / 240, 1 / 60, 0.03, 0.05]) {
    const state = createState(6);
    const brick = bottomBrick(state);
    state.ball = { x: 280, y: 188, r: 7, vx: 0, vy: -ballSpeed(6) };
    let bounced = false;
    for (let i = 0; i < 200 && !bounced; i++) {
      step(state, dt);
      if (Math.sign(state.ball.vy) === DOWN) bounced = true;
    }
    assert.ok(bounced, `must bounce at dt=${dt}`);
    assert.equal(brick.alive, false, `brick destroyed at dt=${dt}`);
  }
});

test('D6 paddle: a fast descent (level 6, 35.5px/step) must not pass through', () => {
  const state = createState(6);
  // bottom edge 440 -> 475.5 in one step: band test [448,460] and AABB both miss
  state.ball = { x: 320, y: 433, r: 7, vx: 0, vy: ballSpeed(6) };
  const lost = step(state, 0.05);
  assert.ok(state.ball.vy < 0, 'must bounce off the paddle');
  assert.ok(state.ball.y + state.ball.r <= PADDLE_Y, 'ball leaves through the top of the paddle');
  assert.equal(lost, false, 'not lost');
});

test('D6b guard: passing beside the paddle (x outside) is still a loss, no false bounce', () => {
  const state = createState(6);
  state.ball = { x: 100, y: 433, r: 7, vx: 0, vy: ballSpeed(6) };
  step(state, 0.05);
  assert.ok(state.ball.vy > 0, 'no bounce when x is outside the paddle');
});

test('D7 speed: a paddle rebound keeps the level speed (renormalized)', () => {
  const state = createState(1);
  state.ball = { x: 344, y: 441.5, r: 7, vx: 0, vy: ballSpeed(1) }; // hit = +0.5
  step(state, 0.01);
  assert.ok(Math.sign(state.ball.vy) < 0, 'paddle bounce happened');
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(norm - ballSpeed(1)) < 1e-6, `norm ${norm} must equal ${ballSpeed(1)}`);
});

test('D8 dead angle: a center paddle hit keeps a minimum horizontal speed', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 441.5, r: 7, vx: 0, vy: ballSpeed(1) }; // hit = 0
  step(state, 0.01);
  assert.ok(Math.sign(state.ball.vy) < 0, 'paddle bounce happened');
  assert.ok(
    Math.abs(state.ball.vx) >= ballSpeed(1) * 0.06,
    `|vx| ${Math.abs(state.ball.vx)} must be >= ${ballSpeed(1) * 0.06}`
  );
});

